    for (let i = 1; i <= N; i++) s.push(i);
  } else {
    for (let i = 1; i < N; i++) s.push(i);
    s.push(N + N / 2);
  }

  const M = 1000;
  const out = [];

  for (let i = 0; i < N; i++) {
    const row = [];
    for (let j = 0; j < N; j++) {
      row.push(M * s[i] + s[j]);
    }
    out.push(row.join(' '));
  }

  console.log(out.join('\n'));
}
